    const latestById = new Map(latest.filter(item => item.id).map(item => [item.id, item]));
    const retainedIds = new Set(draft.filter(item => item.id).map(item => item.id));
    const usedLatest = new Set(latest.flatMap((item, index) => retainedIds.has(item.id) ? [index] : []));
