// Core · 时间派生 / 查询。这里只处理日期语义，不创建任何 Picker 或 DOM。
const TaskTemporalQuery = {
    context() {
        const today = localDateKey();
        return { today, end: addLocalDays(today, 7) };
    },
    isOverdue(source, context = this.context()) {
        if (source?.kind !== "task" || source.completed)
            return false;
        const dueKey = source.dueKey ?? displayDateKey(source.dueDate, source.timeZone);
        return Boolean(dueKey && dueKey < context.today);
    },
    matchesDate(entry, state, context = this.context()) {
        if (state.dateMode === "overdue")
            return this.isOverdue(entry, context);
        if (state.dateMode === "today_or_overdue")
            return entry.kind === "task" && !entry.completed && Boolean(entry.dueKey) && entry.dueKey <= context.today;
        if (state.dateMode === "next7")
            return entry.kind === "task" && !entry.completed && Boolean(entry.dueKey) && entry.dueKey > context.today && entry.dueKey <= context.end;
        if (state.dateMode === "exact" && state.dueDate)
            return entry.dueKey === state.dueDate;
        return true;
    },
    rangeLabel(source) {
        const task = source && typeof source === "object" ? source : {};
        const timeZone = normalizeOptionalText(task.timeZone);
        const startKey = displayDateKey(task.startDate, timeZone);
        const dueKey = displayDateKey(task.dueDate, timeZone);
        const startTime = displayTimeKey(task.startDate, timeZone);
        const dueTime = displayTimeKey(task.dueDate, timeZone);
        const isAllDay = task.isAllDay !== false;
        const formatDate = key => {
            if (!key) return "";
            const [year, month, day] = String(key).split("-");
            return year === String(new Date().getFullYear()) ? `${month}/${day}` : `${year}/${month}/${day}`;
        };
        if (!startKey && !dueKey)
            return "未设置";
        if (isAllDay) {
            if (startKey && dueKey)
                return startKey === dueKey ? formatDate(dueKey) : `${formatDate(startKey)} - ${formatDate(dueKey)}`;
            return formatDate(dueKey || startKey);
        }
        if (startKey && dueKey) {
            if (startKey === dueKey) {
                const date = formatDate(startKey);
                if (startTime && dueTime) return startTime === dueTime ? `${date} ${dueTime}` : `${date} ${startTime} - ${dueTime}`;
                return `${date} ${startTime || dueTime || ""}`.trim();
            }
            const start = `${formatDate(startKey)}${startTime ? ` ${startTime}` : ""}`;
            const due = `${formatDate(dueKey)}${dueTime ? ` ${dueTime}` : ""}`;
            return `${start} - ${due}`;
        }
        const key = dueKey || startKey;
        const time = dueKey ? dueTime : startTime;
        return `${formatDate(key)}${time ? ` ${time}` : ""}`;
    },
    countdownLabel(source) {
        const task = source && typeof source === "object" ? source : {};
        const timeZone = normalizeOptionalText(task.timeZone);
        const targetKey = displayDateKey(task.dueDate, timeZone);
        if (!targetKey)
            return "";
        if (task.kind !== "task" || task.completed)
            return this.resultDateLabel(task.dueDate, task.isAllDay !== false, timeZone);
        const delta = localDateDayDelta(this.context().today, targetKey);
        if (delta === null)
            return this.resultDateLabel(task.dueDate, task.isAllDay !== false, timeZone);
        if (delta === 0)
            return "今天";
        if (delta === 1)
            return "明天";
        if (delta > 1)
            return `剩余${delta}天`;
        return `逾期${Math.abs(delta)}天`;
    },
    instantLabel(value) {
        const millis = normalizeEpochMillis(value);
        if (millis === null) return "";
        const date = new Date(millis);
        const pad = number => String(number).padStart(2, "0");
        const year = date.getFullYear();
        const base = year === new Date().getFullYear()
            ? `${pad(date.getMonth() + 1)}/${pad(date.getDate())}`
            : `${year}/${pad(date.getMonth() + 1)}/${pad(date.getDate())}`;
        return `${base} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
    },
    cardTime(task, field, entry, countdown = false) {
        if (field === "start" || field === "deadline") {
            const value = field === "start" ? task.startDate : task.dueDate;
            const full = this.resultDateLabel(value, task.isAllDay !== false, task.timeZone);
            const overdue = field === "deadline" && this.isOverdue(entry || task);
            return { full, label: field === "deadline" && countdown ? this.countdownLabel(task) : full,
                overdue, dateKey: field === "deadline" ? (entry?.dueKey ?? displayDateKey(task.dueDate, task.timeZone)) : "" };
        }
        const value = field === "created" ? (entry?.createdAt ?? taskCreatedAtMillis(task))
            : field === "modified" ? (entry?.modifiedAt ?? normalizeEpochMillis(task.modifiedTime))
            : field === "completed" && task.kind === "task" && task.completed ? (entry?.completedAt ?? normalizeEpochMillis(task.completedTime)) : null;
        const full = this.instantLabel(value);
        return { full, label: full, overdue: false, dateKey: "" };
    },
    resultDateLabel(date, isAllDay = true, timeZone = "") {
        const key = displayDateKey(date, timeZone);
        if (!key) return "";
        const [year, month, day] = key.split("-");
        const base = year === String(new Date().getFullYear()) ? `${month}/${day}` : `${year}/${month}/${day}`;
        const time = !isAllDay ? displayTimeKey(date, timeZone) : null;
        return time ? `${base} ${time}` : base;
    },
    relativeDateLabel(date, isAllDay = true, timeZone = "") {
        const key = displayDateKey(date, timeZone);
        if (!key) return "无日期";
        const context = this.context();
        const time = !isAllDay ? displayTimeKey(date, timeZone) : null;
        let label;
        if (key === context.today) label = "今天";
        else if (key === addLocalDays(context.today, 1)) label = "明天";
        else if (key < context.today) label = TaskTemporalQuery.resultDateLabel(key, true);
        else label = key.slice(5).replace("-", "/");
        return time ? `${label} ${time}` : label;
    },
};
