            if (!visibleCount && !empty) empty = list.createDiv({ cls: "dida-bridge-view-empty" });
            if (empty) { empty.textContent = sort?.active ? "先点击行选择常驻值" : "没有匹配的筛选值"; empty.hidden = Boolean(visibleCount); }
