        const scope = this.host.contextTaskScope;
        if (scope?.kind) metadata.kind = scope.kind;
        if (!this.host.contextTag && scope?.tags?.length === 1) metadata.tags = normalizeTags([...metadata.tags, scope.tags[0]]);
