        const refs=new Map(),collapsed=new Set();let managing=false,saving=false,unassigned=current==="__unassigned__";
        const departments=this.plugin.settings.feishuDirectory?.departments||[],users=this.plugin.settings.feishuDirectory?.users||[];
        const nodes=new Map(departments.map(d=>[d.id,{...d,children:[],members:[]}]));
        const roots=[],membership=new Set();
