            for(const[key,ref]of refs)if(!seen.has(key)){ref.item.remove();refs.delete(key);}
            if(!seen.size)list.createDiv({cls:"dida-bridge-tag-tree-empty",text:"没有匹配的人员"});
            count.setText(filterMode?`可选 ${members.size}`:`已选 ${selected.size}`);
            count.setAttribute("aria-label",`已选 ${selected.size} 位，可选 ${members.size} 位`);
            strip.render(unassigned?[{key:"__unassigned__",text:config.role==="follower"?"无关注人":"未指派",onActivate:clear}]:[...selected].map(id=>({key:id,text:display(id),onActivate:()=>choose(id)})));
