            if (custom.hidden || pending) return false;
            const keyboard = custom.contains(root.ownerDocument.activeElement) && root.ownerDocument.activeElement?.matches?.(":focus-visible");
            custom.hidden = true; list.hidden = false; onModeChange?.(false);
            if (keyboard) customChoice?.focus({ preventScroll: true });
