        onDispose: () => wrapper.closest(".dida-bridge-results")?._didaViewport?.cancelSwipeReveal(wrapper),
        onAction: (key, action) => {
            // UI can be held during motion, but an action must use the current Task Store identity.
            // A deleted source must not be recreated by the retained row's old closure.
            const latest = owner.plugin.settings.localTasks[task.id];
            if (latest) return owner.runResultSwipeAction(key, latest, action);
        },
