        this.addCommand({ id: "open-task-center", name: "打开飞书任务中心", callback: () => void this.activateTaskCenter() });
        this.addCommand({ id: "open-task-center-tab", name: "在标签页打开飞书任务", callback: () => void this.activateTaskCenterTab() });
