        departments:Array.isArray(directory?.departments)?directory.departments.filter(d=>/^(?:od[-_][A-Za-z0-9_-]+|0)$/.test(d?.id||"")).map(d=>({id:String(d.id),name:String(d.name||d.id),parentId:String(d.parentId||"0")})):[],
        authorizedDepartmentCount:Number(directory?.authorizedDepartmentCount||0), scopeUserCount:Number(directory?.scopeUserCount||0),
