    this.settings.reminderPresets = normalizeReminderPresets(this.settings.reminderPresets);
    this.settings.assigneeRemarks = normalizeAssigneeRemarks(this.settings.assigneeRemarks);
    this.settings.assigneeLayout = normalizeAssigneeLayout(this.settings.assigneeLayout);
    this.settings.mdDefaultProperties = normalizeMdDefaultPropertyProfiles(this.settings.mdDefaultProperties);
    this.settings.lastCreatedMetadata = normalizeCreateMetadata({...this.settings.lastCreatedMetadata,kind:"task"});
    if (!this.settings.projects.some(p => p.id === this.settings.lastCreatedMetadata.projectId))
        this.settings.lastCreatedMetadata.projectId = this.settings.projects[0]?.id || "";
    FEISHU_AUTH_RUNTIME.set(this.settings,new FeishuTenantAuth(this.settings,()=>this.feishuReadSecret(),this.lifecycleAbortController.signal,()=>this.feishuAssertStateCurrent()));
    FEISHU_USER_AUTH_RUNTIME.set(this.settings,new FeishuUserAuth(this.settings,()=>this.feishuReadUserToken(),value=>this.feishuWriteUserToken(value),()=>this.feishuReadSecret(),this.lifecycleAbortController.signal,()=>this.feishuAssertStateCurrent()));
