            const openId=String(info.data?.open_id||""),name=String(info.data?.name||openId);
            if(!/^ou_[A-Za-z0-9_-]+$/.test(openId))throw fsError("飞书没有返回可核验的当前用户 open_id，未保存授权",502);
            if(this.settings.feishuUserInfo?.openId && this.settings.feishuUserInfo.openId!==openId)
                throw fsError("当前仓库已绑定另一名飞书用户；为防任务混入请先明确解除旧个人授权，或使用独立仓库",409);
