            const verifySettings={...this.settings,feishuUserConnected:true,feishuUserInfo:{openId,name}};
            const verifyAuth=new FeishuUserAuth(verifySettings,()=>JSON.stringify({appId,openId,accessToken:token,refreshToken,expiresAt:flow.grantedAt+life*1000}),()=>{},()=>secret,this.lifecycleAbortController.signal);
            verifyAuth.token=token;verifyAuth.expiresAt=flow.grantedAt+life*1000;
            FEISHU_USER_AUTH_RUNTIME.set(verifySettings,verifyAuth);
