            const userAuth=new FeishuUserAuth(this.settings,()=>this.feishuReadUserToken(),value=>this.feishuWriteUserToken(value),()=>this.feishuReadSecret(),this.lifecycleAbortController.signal,()=>this.feishuAssertStateCurrent());
            userAuth.token=token;userAuth.expiresAt=flow.grantedAt+life*1000;
            FEISHU_USER_AUTH_RUNTIME.set(this.settings,userAuth);
