    getOrderedProjectEntries(){return this.settings.projects.map(project=>({project,depth:0,folder:null}));},
    isLocalProjectFolder(){return false;},
    async reorderProjectRootItems(){throw fsError("本轮不把本地拖动伪装为飞书清单排序");},
    async reorderProjectsInFolder(){throw fsError("飞书清单分组尚未接入");},
    async moveProjectToFolder(){throw fsError("飞书清单分组尚未接入");},
    async createProjectFolder(){throw fsError("本轮只接入飞书清单，不创建虚假的清单文件夹");},
