const DidaBridgeNoteImportModule = {
    async importBoundNote(taskId, file) {
        const epoch=this.getBoundNoteEpoch(taskId),currentEpoch=()=>this.isBoundNoteEpoch(taskId,epoch);
        return this.runOperation(async () => {
            if(!currentEpoch())return;
            taskId=fsResolveTaskId(this.settings,taskId);
            let parsedSuccessfully = false;
            let shouldNormalizeNote = false;
            const revisionAtRead = this.getBoundNoteRevision(taskId);
            try {
                if (this.isBoundNoteRecoveryPending(taskId) || !this.isInCanonicalBoundNoteFolder(file.path)) return;
                let task = this.settings.localTasks[taskId];
                if(task?.kind==="note")throw fsError("历史 NOTE 为只读保留数据，不导入或改写",409);
                if(task?.feishu?.parentTaskGuid)return;
                const boundPath = this.settings.noteBindings[taskId];
                if (!task || !boundPath || boundPath !== file.path)
                    return;
                const raw = await this.readBoundNoteSource(file);
                if (!currentEpoch() || this.unloading || this.isBoundNoteRecoveryPending(taskId) || this.settings.noteBindings[taskId] !== file.path) return;
                if (!this.isBoundNoteFileIdentity(raw, taskId)) {
                    this.markBoundNoteForRecovery(taskId,`MD 的 dida-id 缺失、不匹配或 YAML 无法识别：${file.path}；未接管文件，请核对任务 ID`);
                    await this.saveSettings();
                    return;
                }
                if (this.getBoundNoteRevision(taskId) !== revisionAtRead) {
                    this.scheduleBoundNoteImport(taskId, file, 0);
                    return;
                }
                // 读取 MD 的等待期间，负责人、日期或优先级可能已更新；MD 端只合入文件名标题和完整描述；所有复选框均属于描述文字。
                task = this.settings.localTasks[taskId];
                if (!task) return;
                const parsed = parseBoundTaskNote(raw, task, this.getBoundNoteState(taskId), file);
                shouldNormalizeNote = parsed.nativeNormalizationNeeded || parsed.markerCleanupNeeded || !boundFrontmatterMatchesTask(raw, task);
                // 这份 raw 是本轮明确读取并接受的 MD 修订；完整描述进入同一个主任务 Desired State，不传入任何子任务字段。
                const content=String(parsed.content??"");
                const taskChanged=parsed.title!==task.title || content!==String(task.content??"");
                if(taskChanged) {
                    this.noteOriginDirty.add(taskId);
                    await this.store.updateTask(taskId,{...task,title:parsed.title,content});
                }
                const currentRaw=await this.readBoundNoteSource(file);
                if(!currentEpoch())return;
                if(this.getBoundNoteRevision(taskId)!==revisionAtRead || currentRaw!==raw || this.settings.noteBindings[taskId]!==file.path) {
                    (this.settings.boundNoteStates[taskId] ||= {}).importBlocked=true;
                    this.scheduleBoundNoteImport(taskId,file,0);
                    return;
                }
                this.setBoundNoteBaseline(taskId,raw);
                const acceptedState=this.settings.boundNoteStates[taskId] ||= {};
                delete acceptedState.importBlocked;delete acceptedState.importIssue;
                acceptedState.projectedBasename=markdownBoundTitle(file,task.title);
                await this.saveSettings();
                if(!currentEpoch())return;
                if(this.getBoundNoteRevision(taskId)!==revisionAtRead) {
                    acceptedState.importBlocked=true;
                    this.scheduleBoundNoteImport(taskId,file,0);
                    return;
                }
                this.boundNoteIssues?.delete(taskId);
                if (shouldNormalizeNote) this.deferredBoundNoteSync.add(taskId);
                parsedSuccessfully = true;
                if (this.noteOriginDirty.has(taskId)) {
                    await this.refreshTaskViews();
                    if(currentEpoch())this.scheduleAutoPush(AUTO_PUSH_FAST_DELAY, [taskId], {exact:true});
                }
            }
            catch(error) {
                if(!currentEpoch())return;
                (this.settings.boundNoteStates[taskId] ||= {}).importBlocked=true;
                this.boundNoteIssues ||= new Map();
                this.recordBoundNoteIssue(taskId,{taskId,blockedRevision:revisionAtRead,message:`MD「${file.basename||taskId}」未导入：${errorMessage(error)}。原文件保留，修改后会重新核对。`});
                this.pendingNoteImports.delete(taskId);this.deferredBoundNoteSync.delete(taskId);
                this.syncStatus="error";this.notifyTransientViews();
                throw error;
            }
            finally {
                if(!currentEpoch())return;
                const accepted = parsedSuccessfully && this.getBoundNoteRevision(taskId) === revisionAtRead;
                if (accepted || !this.settings.localTasks[taskId] || this.settings.noteBindings[taskId] !== file.path)
                    this.pendingNoteImports.delete(taskId);
                if (accepted && !this.noteOriginDirty.has(taskId) && (this.deferredBoundNoteSync.has(taskId) || shouldNormalizeNote))
                    void this.syncBoundNote(taskId, { allowActiveEditorUpdate: true }).catch(error => {
                        console.warn("[Dida Bridge] 绑定笔记导入后回写失败", error);
                    });
            }
        });
    },
};

const DidaBridgeTaskWriteModule = {
    async addTask(input, refreshViews = true) {
        return this.runOperation(async () => {
            if (!this.isConfigured())
                throw new Error("请先完成 Dida Bridge 配置");
            if (!this.getProject(input.projectId))
                throw new Error("目标清单不可用，请刷新清单后重试");
            const created = await this.store.appendTask(input);
            this.invalidateTaskRuntime();
            if (refreshViews)
                await this.refreshTaskViews({ invalidateRuntime: false });
            return created;
        });
    },
    async updateTaskTransaction(taskId, resolveInput, refreshViews = true) {
        return this.runOperation(async () => {
            if (!this.isConfigured())
                throw new Error("请先完成 Dida Bridge 配置");
            const existing = this.settings.localTasks[taskId];
            if (!existing)
                throw new Error("没有找到该任务");
            const resolved = await resolveInput(existing);
            if (!resolved || resolved.abort)
                return { ...(resolved ?? {}), abort: true, changed: false, task: existing };
            const input = resolved.input;
            if(input && fsNeedsWholeCompletion(this.settings,existing,input)) {
                if(!await fsConfirmWholeTask(this))return {abort:true,changed:false,latestTask:existing,validationError:"已取消完成整个多人任务"};
            }
            if (!input || !this.getProject(input.projectId))
                throw new Error("目标清单不可用，请刷新清单后重试");
            const previousTask = { ...existing, checklistItems: normalizeChecklistItems(existing.checklistItems).map(item => ({ ...item })) };
            const changed = await this.store.updateTask(taskId, input);
            if (!changed)
                throw new Error("没有找到该任务");
            this.invalidateTaskRuntime();
            await this.syncBoundNote(taskId, { allowActiveEditorUpdate: true, previousTask });
            if (refreshViews)
                await this.refreshTaskViews({ invalidateRuntime: false });
            const stored = this.settings.localTasks[taskId];
            return { ...resolved, abort: false, changed: true, task: stored };
        });
    },
    async updateTask(taskId, input, refreshViews = true) {
        const result = await this.updateTaskTransaction(taskId, () => ({ input }), refreshViews);
        return result.changed;
    },
    async updateTasksBatch(changes, refreshViews = true) {
        const entries = (Array.isArray(changes) ? changes : [])
            .filter(item => item && item.taskId && typeof item.resolveInput === "function");
        if (!entries.length)
            return { changed: 0, changedIds: [] };
        // 绑定 MD 的任务继续走单任务正式事务，保留“本端持久化 -> MD 投影”的逐项失败边界。
        if (entries.some(item => Boolean(this.settings.noteBindings[item.taskId]))) {
            const changedIds = [];
            try {
                for (const entry of entries) {
                    const result = await this.updateTaskTransaction(entry.taskId, latest => {
                        const input = entry.resolveInput(latest);
                        return input ? { input } : { abort: true };
                    }, false);
                    if (result.changed)
                        changedIds.push(entry.taskId);
                }
            }
            catch (error) {
                if (error && typeof error === "object") {
                    error._didaBatchChangedIds = changedIds.slice();
                }
                throw error;
            }
            if (refreshViews)
                await this.refreshTaskViews({ invalidateRuntime: false });
            return { changed: changedIds.length, changedIds };
        }
        return this.runOperation(async () => {
            if (!this.isConfigured())
                throw new Error("请先完成 Dida Bridge 配置");
            const changedIds = [];
            let dirty = false;
            try {
                for (const entry of entries) {
                    const existing = this.settings.localTasks[entry.taskId];
                    if (!existing)
                        throw new Error("没有找到该任务");
                    // 意图在本端队列真正执行时合并到最新任务，批量入口不保存/回写过时的整任务副本。
                    const input = entry.resolveInput(existing);
                    if (!input)
                        continue;
                    if(fsNeedsWholeCompletion(this.settings,existing,input) && !await fsConfirmWholeTask(this))continue;
                    if (!this.getProject(input.projectId))
                        throw new Error("目标清单不可用，请刷新清单后重试");
                    const changed = await this.store.updateTask(entry.taskId, input, false);
                    if (!changed)
                        throw new Error("没有找到该任务");
                    dirty = true;
                    changedIds.push(entry.taskId);
                }
                if (dirty)
                    await this.saveSettings();
            }
            catch (error) {
                // 与旧逐任务行为一致：已经成功写入内存的前序任务不能因后续失败而静默丢失。
                if (dirty)
                    await this.saveSettings().catch(() => undefined);
                this.invalidateTaskRuntime();
                if (error && typeof error === "object") {
                    error._didaBatchChangedIds = changedIds.slice();
                }
                throw error;
            }
            this.invalidateTaskRuntime();
            if (refreshViews)
                await this.refreshTaskViews({ invalidateRuntime: false });
            return { changed: changedIds.length, changedIds };
        });
    },
    async setTaskCompletion(taskId, completed, refreshViews = true, guardTag = "") {
        const changed = await this.runOperation(async () => {
            const task = this.settings.localTasks[taskId];
            if (!task)
                throw new Error("没有找到该任务");
            if (guardTag && !this.workbenchTaskHasTag(task, guardTag))
                throw new Error("任务已不属于当前项目，请刷新后重试");
            if (task.kind !== "task")
                throw new Error("笔记不能执行完成操作");
            if (task.completed === completed)
                return false;
            if(fsAssigneeIds(task).length>1 && completed && !await fsConfirmWholeTask(this))return false;
            const previousTask = { ...task, checklistItems: normalizeChecklistItems(task.checklistItems).map(item => ({ ...item })) };
            const stored = await this.store.setTaskCompleted(taskId, completed);
            if (!stored)
                throw new Error("没有找到该任务");
            this.invalidateTaskRuntime();
            await this.syncBoundNote(taskId, { allowActiveEditorUpdate: true, previousTask });
            if (refreshViews)
                await this.refreshTaskViews({ invalidateRuntime: false });
            this.notifyTransientViews();
            return true;
        });
        if (changed)
            this.scheduleAutoPush(AUTO_PUSH_FAST_DELAY, [taskId]);
        return changed;
    },
};
const DidaBridgeTaskDeleteModule = {

    async removeLocalTaskState(taskId) {
        taskId=fsResolveTaskId(this.settings,taskId);
        const aliases=Object.keys(this.settings.taskIdAliases||{}).filter(id=>fsResolveTaskId(this.settings,id)===taskId);
        const ids=[taskId,...aliases],messages=new Set();
        for(const id of ids) {
            const message=this.taskSyncStates.get(id)?.message;
            if(message)messages.add(fsSafeMessage(message));
        }
        const task=this.settings.localTasks[taskId],tombstone=this.settings.deletedTaskTombstones[taskId] ||= {deletedAt:Date.now(),projectId:task?.projectId||""};
        if(task && !tombstone.restoreData)tombstone.restoreData=fsClone(task);
        tombstone.detailRecoveries=this.settings.taskDetailRecoveries.filter(record=>ids.includes(record.taskId));
        await this.detachBoundTaskNote(taskId,{reason:"用户删除任务，本地记录退役",refresh:false,deferSave:true,force:true});
        for(const id of ids) {
            this.removeAutoPushTaskIds([id]);this.autoPushTaskIds.delete(id);this.autoPushExactIds?.delete(id);this.deferredAutoPushTaskIds.delete(id);
            this.taskSyncStates.delete(id);this.boundNoteIssues?.delete(id);this.clearBoundNoteRuntime(id);
            delete this.settings.feishuConflicts[id];delete this.settings.localTasks[id];delete this.settings.snapshots[id];
            delete this.settings.feishuSubtasks[id];clearMutationReceipt(this.settings,id);
            delete this.settings.noteBindings[id];this.markTaskRemoteMissing(id,false);
        }
        this.settings.taskDetailRecoveries=this.settings.taskDetailRecoveries.filter(record=>!ids.includes(record.taskId));
        for(const index of Object.values(this.settings.feishuSubtasks||{}))for(const field of ["ids","viewOrder"])if(Array.isArray(index[field]))index[field]=index[field].filter(id=>!ids.includes(id));
        // Exact duplicate task diagnostics only; independent connection/permission errors survive.
        if(tombstone.deleteMessage)messages.add(fsSafeMessage(tombstone.deleteMessage));
        const ownedIssue=entry=>entry?.taskId?fsResolveTaskId(this.settings,entry.taskId)===taskId:[...messages].some(message=>fsSameTaskIssue(this.settings,entry,taskId,message));
        for(const [key,entry] of Object.entries(this.feishuOperationIssues||{}))if(ownedIssue(entry))delete this.feishuOperationIssues[key];
        if(this.globalSyncIssue && ownedIssue(this.globalSyncIssue))this.globalSyncIssue=null;
        // Keep aliases and the durable tombstone: late responses and a restart must not resurrect the GUID.
    },
    async deleteRemoteTask(api,task){
        const result=await api.deleteTask(task.projectId,task.id,{allowMissingTask:true});
        return {...result,projectId:task.projectId};
    },

    async deleteTasks(taskIds, refreshViews = true) {
        return this.runRemoteOperation(async () => {
            const unique = [...new Set(taskIds.map(id=>fsResolveTaskId(this.settings,id)))].map(id => this.settings.localTasks[id]).filter((task) => Boolean(task));
            if (!unique.length)
                return { deleted: 0, failed: [] };
            const remoteTasks = unique.filter(task => !String(task.id || "").startsWith("local:"));
            if (remoteTasks.length && !this.isConfigured())
                throw new Error("删除远端任务前请先填写 Access Token");
            const api = remoteTasks.length ? new FeishuTaskApi(this.settings, this.lifecycleAbortController.signal) : null;
            const failed = [];
            let deleted = 0,retired = false;
            for (const task of unique) {
                try {
                    if(task.kind==="note")throw fsError("历史笔记为只读保留数据，请在原系统核对；本插件不删除",409);
                    if(this.settings.feishuTransactions?.[task.id])throw fsError("该任务创建结果尚未确认，请先推送回查身份，不能直接删除本端记录");
                    let remoteProjectId = "";
                    if (!task.id.startsWith("local:")) {
                        const remote = await this.deleteRemoteTask(api, task);
                        remoteProjectId = remote.projectId;
                        this.settings.deletedTaskTombstones[task.id] = {
                            projectId: remoteProjectId || String(this.settings.snapshots[task.id]?.projectId || task.projectId || ""),
                            deletedAt: Date.now(),reason:remote.notFound?"explicit-delete-task-not-found":"explicit-delete-success",deleteMessage:remote.message||"",
                        };
                    }
                    await this.removeLocalTaskState(task.id);retired=true;
                    await this.saveSettings();
                    deleted += 1;
                }
                catch (error) {
                    failed.push({ taskId: task.id, title: task.title, message: (fsTaskRetired(this.settings,task.id)?"任务已从当前会话移除，但本地收尾未确认持久化；重启后可能需再次处理。":"")+errorMessage(error, "删除失败") });
                }
            }
            if (retired) {
                this.invalidateTaskRuntime();
                this.reconcileBoundNoteRuntimeState();
            }
            if (refreshViews)
                await this.refreshTaskViews({ invalidateRuntime: false });
            this.syncStatus="success";
            if(failed.length || fsCollectSyncIssues(this).length)this.syncStatus="error";
            this.notifyTransientViews();
            return { deleted, failed };
        });
    }
,
    async deleteTask(taskId, refreshViews = true) {
        const result = await this.deleteTasks([taskId], refreshViews);
        if (result.failed.length)
            throw new Error(result.failed[0].message);
        if (result.deleted === 0)
            throw new Error("没有找到该任务");
    },
};
const DidaBridgeAutoPushModule = {
    async autoPushNow(options={}){
        // Only explicitly edited task IDs are eligible. No startup/global sweep and no automatic failure retry.
        if(!this.isConfigured()||this.unloading||!options.taskIds?.length)return;
        try{return await this.pushTasksToRemote(options.taskIds,{showNotice:false,exactTaskIds:options.exactTaskIds});}
        catch(error){if(!this.unloading)new obsidian_1.Notice(errorMessage(error,"本端修改已保留，飞书推送失败"),5000);}
    },
};

const DidaBridgeCurrentStateModule = {
    currentStateSyncConfigured(){return this.isConfigured() && this.settings.feishuAutoRefresh===true;},
    currentStatePollDelay(){return Math.max(60,Number(this.settings.feishuRefreshSeconds)||120)*1000;},
    currentStateErrorDelay(){return Math.max(120000,this.currentStatePollDelay());},
    currentStateCanRun(){return this.currentStateEnabled && !this.unloading && navigator.onLine!==false && !document.hidden && this.currentStateSyncConfigured() && !this.currentStateRunning;},
    startCurrentStateSync(){this.currentStateEnabled=true;this.scheduleCurrentStatePull(0);},
    stopCurrentStateSync(){this.currentStateEnabled=false;this.pauseCurrentStateSync();},
    pauseCurrentStateSync(){if(this.currentStateTimer!==null)window.clearTimeout(this.currentStateTimer);this.currentStateTimer=null;},
    markCurrentStateActivity(){if(Date.now()-(this._feishuLastPullAt||0)>30000)this.scheduleCurrentStatePull(0);},
    scheduleCurrentStatePull(delayMs=120000){
        if(!this.currentStateEnabled||!this.currentStateSyncConfigured()||this.unloading)return;
        this.pauseCurrentStateSync();
        const delay=delayMs<=0?500:Math.max(60000,delayMs);
        this.currentStateTimer=window.setTimeout(()=>{this.currentStateTimer=null;void this.currentStatePullTick();},delay);
    },
    async currentStatePullTick(){
        if(!this.currentStateCanRun())return;
        this.currentStateRunning=true;
        try {await this.feishuPull(false);this._feishuLastPullAt=Date.now();}
        catch(error){this.globalSyncIssue={message:errorMessage(error,"飞书读取失败，缓存保留")};this.syncStatus="error";this.notifyTransientViews();}
        finally{this.currentStateRunning=false;this.scheduleCurrentStatePull(this.currentStatePollDelay());}
    },
};

const DidaBridgeManualSyncModule = {
    async manualSyncNow(showNotice=true){
        if(this.manualSyncPromise)return this.manualSyncPromise;
        this.feishuOperationIssues ||= {};delete this.feishuOperationIssues["手动同步"];
        const promise=this.manualSyncCore(showNotice);this.manualSyncPromise=promise;
        try{return await promise;}catch(error){this.syncStatus="error";
            this.feishuOperationIssues["手动同步"]={message:errorMessage(error,"飞书同步失败，缓存保留")};this.notifyTransientViews();
            if(showNotice)new obsidian_1.Notice(`${errorMessage(error,"飞书同步失败，缓存保留")}。点击顶部同步状态查看详情。`,6000);return null;}
        finally{if(this.manualSyncPromise===promise)this.manualSyncPromise=null;}
    },
    async manualSyncCore(showNotice){
        if(!this.isConfigured())throw fsError("请先在设置中登录你的飞书");
        // Explicit full sync: a fresh pull first detects concurrent edits, then pushes only still-pending work.
        const result=await this.feishuPull(false);
        const ids=Object.keys(this.settings.localTasks).filter(id=>this.hasPendingLocalPush(id));
        const pushed=ids.length?await this.pushTasksToRemote(ids,{showNotice:false}):null;
        this.syncStatus="success"; // detailed stage stores below remain authoritative
        const issues=fsCollectSyncIssues(this),errorCount=issues.length;
        this.syncStatus=errorCount?"error":"success";this.notifyTransientViews();
        if(showNotice)new obsidian_1.Notice(`飞书同步：读取 ${result?.remoteCount||0} 项 · 写入 ${pushed?.pushed||0} 项${errorCount?` · ${issues[0].phase}：${issues[0].message}。点击顶部状态查看 ${errorCount} 项详情。`:""}`,errorCount?6500:3500);
        return {pull:result,push:pushed};
    },
};

const DidaBridgeManualPushModule = {
    async pushTasksToRemote(taskIds,options={}){
        const requested=[...new Set((Array.isArray(taskIds)?taskIds:[]).filter(Boolean))];
        if(!this.isConfigured())throw fsError("请先登录你的飞书");
        return this.runRemoteOperation(async()=>{
            this.beginRemoteActivity();
            try {
                await this.operationQueue;
                await this.flushPendingBoundNoteImports({verifyAll:true});
                const previousNotes=this.captureBoundTaskComparisons();
                const result=await this.syncEngine.pushLocal({taskIds:requested,exactTaskIds:options.exactTaskIds,shouldAbort:()=>this.unloading,signal:this.lifecycleAbortController.signal,beforeTask:taskId=>this.flushPendingBoundNoteImports({taskIds:[taskId]})});
                this.feishuOperationIssues ||= {};delete this.feishuOperationIssues["写入飞书"];
                for(const id of result.updatedLocalTaskIds||[])this.setTaskSyncState(id,null);
                const failed=[...(result.createErrors||[]),...(result.taskErrors||[])];
                for(const e of failed)this.setTaskSyncState(e.taskId,e.syncState||"failed",e.message,{autoRetry:false});
                for(const {from} of result.remappedIds||[])this.taskSyncStates.delete(from);
                await this.remapTaskViewIds(result.remappedIds||[]);
                const notes=await this.syncAllBoundNotes(previousNotes);
                this.invalidateTaskRuntime();
                try {await this.refreshTaskViews({invalidateRuntime:false});}catch(_){/* remote facts already checkpointed */}
                this.notifyTransientViews();this.syncStatus=failed.length||notes.failures.length?"error":"success";
                const summary={pushed:result.createdCount+result.updatedRemoteCount,recreated:0,updated:result.updatedRemoteCount,
                    confirmed:0,skipped:result.skippedIds.length,failed,noteErrors:notes.failures,pending:[],remappedIds:result.remappedIds};
                if(options.showNotice||failed.length)new obsidian_1.Notice(failed.length?`飞书推送：成功 ${summary.pushed} · 失败 ${failed.length}。${failed[0].message}`:`已推送到飞书 ${summary.pushed} 项`,failed.length?7000:3500);
                return summary;
            } catch(error) {
                this.syncStatus="error";(this.feishuOperationIssues ||= {})["写入飞书"]={message:errorMessage(error,"写入飞书失败，原文保留")};throw error;
            } finally {await this.finishRemoteActivity();}
        });
    },
};



function didaResultComparator(settings) {
        const field = TaskCenterResultViewModel.sortDefinition(settings.resultSortField).field;
        const multiplier = settings.resultSortDirection === "asc" ? 1 : -1;
        return (a, b) => {
            const av = a[field];
            const bv = b[field];
            const aMissing = av === null || !Number.isFinite(av);
            const bMissing = bv === null || !Number.isFinite(bv);
            // 时间排序共用原始时间戳；缺失值在两个方向都沉底，不借用其他时间伪装。
            if (aMissing !== bMissing)
                return aMissing ? 1 : -1;
            if (!aMissing && av !== bv)
                return (av - bv) * multiplier;
            // 主排序相同时，创建时间固定倒序做稳定 tie-break，避免卡片来回抖动。
            const createdDiff = (Number(b.createdAt) || 0) - (Number(a.createdAt) || 0);
            if (createdDiff)
                return createdDiff;
            return String(a.id || "").localeCompare(String(b.id || ""));
        };
}
const WORKBENCH_SORT_OWNER = Symbol.for("dida.workbench-sort");
function mountDidaSortControl(parent, settings, apply, showPicker) {
    const control = parent.createDiv({ cls: "dida-bridge-sort-control", attr: { role: "group", "aria-label": "任务排序" } });
    const field = createDidaButton(control, "choice", { cls: "dida-bridge-sort-trigger dida-bridge-sort-field-trigger", attr: { type: "button" } });
    field.createSpan({ cls: "dida-bridge-sort-trigger-label" });
    const picker = createDidaButton(control, "action", { cls: "dida-bridge-view-icon-action dida-bridge-sort-picker-trigger", attr: { type: "button" } });
    const direction = createDidaButton(control, "choice", { cls: "dida-bridge-sort-direction-trigger", attr: { type: "button" } });
    direction.createSpan({ cls: "dida-bridge-sort-trigger-icon", attr: { "aria-hidden": "true" } });
    field.addEventListener("click", () => {
        const fields = TaskCenterResultViewModel.enabledSorts(settings);
        if (fields.length) apply({ resultSortField: fields[(fields.indexOf(settings.resultSortField) + 1) % fields.length] });
    });
    direction.addEventListener("click", () => apply({ resultSortDirection: settings.resultSortDirection === "asc" ? "desc" : "asc" }));
    picker.addEventListener("click", () => showPicker(picker));
    return control;
}

// Immutable host scope is separate from user-clearable filters and saved browse state.
function createDidaTaskScope(input = null, tag = "", canonical = value => value) {
    const raw = tag ? [tag] : Array.isArray(input?.tags) ? input.tags : null;
    const tags = raw === null ? null : [...new Set(normalizeTags(raw).map(value => canonical(value)))].sort();
    const excludedTags = [...new Set(normalizeTags(input?.excludedTags || []).map(value => canonical(value)))].sort();
    const kind = ["task", "note"].includes(input?.kind) ? input.kind : "";
    return { assignee: typeof input?.assignee === "string" ? input.assignee : null, tags, tagKeys: tags === null ? null : new Set(tags.map(tagIdentityKey)), kind,
        excludedTagKeys: new Set(excludedTags.map(tagIdentityKey)),
        key: tags === null && !kind && !excludedTags.length && typeof input?.assignee !== "string" ? "" : JSON.stringify([kind, input?.assignee ?? null, tags?.map(tagIdentityKey), ...(excludedTags.length ? [excludedTags.map(tagIdentityKey)] : [])]) };
}
function matchesDidaTaskScope(entry, scope, canonical = value => value) {
    if (!entry) return false;
    if (!scope) return true;
    if (scope.assignee !== null && scope.assignee !== undefined && !fsAssigneeIds(entry.task||entry).some(id=>fsAssigneeIds(scope.assignee).includes(id))) return false;
    if (scope.kind && (entry.kind === "note" ? "note" : "task") !== scope.kind) return false;
    if (scope.tagKeys === null && !scope.excludedTagKeys?.size) return true;
    const tags = entry.canonicalTags ?? normalizeTags(entry.tags).map(value => canonical(value));
    if (scope.excludedTagKeys?.size && tags.some(tag => scope.excludedTagKeys.has(tagIdentityKey(tag)))) return false;
    return scope.tagKeys === null || tags.some(tag => scope.tagKeys.has(tagIdentityKey(tag)));
}

