class DidaDialogModal extends obsidian_1.Modal {
    constructor(app, options = {}) {
        super(app);
        this.options = options;
        this.swipeBack = options.swipeBack ?? null;
        this.swipeBackCleanup = null;
        this.dialogScope = new DisposableScope();
        this.dialogSubmission = createDidaDialogSubmission(this.modalEl, () => this.isDialogActive(), () => this.close());
    }
    isDialogActive() {
        return !this.didaClosing && Boolean(this.modalEl?.isConnected) && this.options.isOwnerActive?.() !== false;
    }
    bindSwipeBack() {
        this.swipeBackCleanup?.();
        this.swipeBackCleanup = this.swipeBack?.register(this.modalEl, {
            canGoBack: () => this.isDialogActive(), back: () => this.close(),
        }, [this.modalEl.closest(".modal-container")]) ?? null;
    }
    disposeSwipeBack() {
        this.swipeBackCleanup?.();
        this.swipeBackCleanup = null;
    }
    bindDialogKeys(root) {
        const onKey = event => {
            if (trapDialogTab(root, event)) return;
            event.stopPropagation();
            if (event.isComposing || event.keyCode === 229) return;
            if (event.key === "Escape") { event.preventDefault(); this.close(); }
        };
        root.addEventListener("keydown", onKey);
        this.dialogScope.add(() => root.removeEventListener("keydown", onKey));
    }
    focusDialogInput(input, select = false) {
        // Dialog Frame 由 CSS 唯一拥有。键盘/visualViewport 只影响可见区域，
        // 不再通过 JS 重算 left/top/maxHeight，避免 iOS 键盘动画期间位置往返抖动。
        const focus = () => {
            if (!this.isDialogActive() || !input.isConnected) return;
            input.focus({ preventScroll: true });
            if (select) input.select();
        };
        // 宿主已挂载时直接沿本次用户手势聚焦；仅未挂载时等一帧，不主动收键盘再补救。
        if (this.modalEl.isConnected) focus();
        else {
            const view = this.modalEl.ownerDocument.defaultView || window;
            const frame = view.requestAnimationFrame(focus);
            this.dialogScope.add(() => view.cancelAnimationFrame(frame));
        }
    }
    close(restoreFocus = true, { force = false } = {}) {
        if (this.didaClosing) return true;
        if (this.dialogSubmission.busy && !force) return false;
        const doc = this.modalEl.ownerDocument;
        const active = doc.activeElement;
        const canReturn = restoreFocus !== false && this.options.returnFocusEl
            && this.options.isOwnerActive?.() !== false
            && (this.modalEl.contains(active) || active === doc.body);
        const focus = this.options.returnFocusEl?.isConnected ? this.options.returnFocusEl : this.options.returnFocusFallback;
        this.didaClosing = true;
        this.disposeSwipeBack();
        this.dialogScope.dispose();
        const container = this.modalEl?.closest(".modal-container");
        container?.classList.add("is-dida-dialog-closed");
        try { super.close(); } finally { container?.remove?.(); }
        // 仅键盘发起且父层仍有效时返回。失效/替换/触控路径不强制拉起输入法。
        if (canReturn && this.options.isOwnerActive?.() !== false && focus?.isConnected && !focus.disabled
            && (doc.activeElement === doc.body || doc.activeElement === focus || !doc.activeElement?.isConnected))
            focus.focus({ preventScroll: true });
        return true;
    }

    onClose() {
        this._hoverHintObserver?.disconnect();
        this._hoverHintObserver = null;
        this.didaClosing = true;
        this.disposeSwipeBack();
        this.dialogScope.dispose();
    }
}
