// Vault paths use the existing dialog, search and tree-row primitives. Selecting a
// missing path only saves the preference; its existing writer creates it on use.
class DidaVaultFolderModal extends DidaDialogModal {
    onOpen() {
        this.modalEl.addClass("dida-bridge-vault-folder-modal", "dida-bridge-picker-surface");
        this.modalEl._dbPopupScope = this.dialogScope;
        const body = prepareDidaDialogShell(this, this.options.title, "folder");
        const input = TaskCenterPickerPrimitiveModule.createPickerSearch(body, "搜索文件夹或输入新路径");
        const list = body.createDiv({ cls: "dida-bridge-picker-list dida-bridge-vault-folder-list" });
        const footer = TaskCenterPickerPrimitiveModule.createPickerFooter(body);
        footer.createSpan({ cls: "dida-bridge-vault-folder-current", text: this.options.initialValue,
            attr: { "aria-description": `当前目录：${this.options.initialValue}` } });
        const cancel = createDidaButton(footer, "action", { cls: "dida-bridge-dialog-button", text: "取消", attr: { type: "button" } });
        cancel.onclick = () => this.close();
        const root = this.app.vault.getRoot();
        const folders = [];
        const collect = folder => {
            for (const child of folder.children) if (child instanceof obsidian_1.TFolder) { folders.push(child); collect(child); }
        };
        collect(root);
        const childrenOf = folder => folder.children.filter(child => child instanceof obsidian_1.TFolder)
            .sort((a, b) => a.name.localeCompare(b.name, "zh-CN", { numeric: true }));
        const choose = path => {
            if (!this.isDialogActive() || this.dialogSubmission.busy) return;
            const normalized = normalizeVaultRelativeFolder(path, "");
            if (!normalized) return;
            const parts = normalized.split("/");
            for (let end = 1; end <= parts.length; end++) {
                const target = this.app.vault.getAbstractFileByPath(parts.slice(0, end).join("/"));
                if (target && !(target instanceof obsidian_1.TFolder)) {
                    new obsidian_1.Notice("该路径包含同名文件，请选择其他目录"); return;
                }
            }
            void this.dialogSubmission.submit(() => this.options.onSubmit(normalized),
                [input, ...list.querySelectorAll("button")], "保存目录失败");
        };
        const addFolder = (host, folder, depth, flat = false) => {
            const item = host.createDiv();
            let branch = null;
            const children = flat ? [] : childrenOf(folder);
            const view = createDidaPickerTreeRow(item, { name: flat ? folder.path : folder.name,
                label: folder.path, depth, icon: "folder", hasChildren: children.length > 0,
                selected: folder.path === this.options.initialValue, onToggle: () => toggle() });
            view.button.onclick = () => choose(folder.path);
            const toggle = () => {
                if (this.dialogSubmission.busy) return;
                if (!branch) {
                    branch = item.createDiv();
                    syncDidaPickerTreeBranch(branch, depth + 1);
                    for (const child of children) addFolder(branch, child, depth + 1);
                } else branch.hidden = !branch.hidden;
                const expanded = !branch.hidden;
                view.toggle.setAttribute("aria-expanded", String(expanded));
                view.toggle.setAttribute("aria-label", `${expanded ? "折叠" : "展开"} ${folder.name}`);
                (0, obsidian_1.setIcon)(view.toggle, expanded ? "chevron-down" : "chevron-right");
            };
            if (children.length && this.options.initialValue.startsWith(`${folder.path}/`)) toggle();
        };
        const render = () => {
            if (!this.isDialogActive() || this.dialogSubmission.busy) return;
            list.empty();
            const query = input.value.trim(), lower = query.toLocaleLowerCase();
            if (!query) {
                for (const folder of childrenOf(root)) addFolder(list, folder, 0);
            } else {
                const matches = folders.filter(folder => folder.path.toLocaleLowerCase().includes(lower))
                    .sort((a, b) => a.path.localeCompare(b.path, "zh-CN", { numeric: true }));
                for (const folder of matches) addFolder(list, folder, 0, true);
                const path = normalizeVaultRelativeFolder(query, "");
                if (path && !this.app.vault.getAbstractFileByPath(path)) {
                    TaskCenterPickerPrimitiveModule.createPickerRow(list, { value: path, label: `使用新路径：${path}`, icon: "folder-plus" },
                        { showCheck: false, onChoose: choose });
                }
            }
            if (!list.childElementCount) list.createDiv({ cls: "dida-bridge-vault-folder-empty", text: query ? "没有匹配的文件夹" : "输入路径，首次使用时创建目录" });
        };
        bindRafInput(input, this.modalEl, render);
        this.dialogScope.event(input, "keydown", event => {
            if (event.isComposing || event.keyCode === 229) return;
            if (event.key === "ArrowDown") { event.preventDefault(); list.querySelector("button:not(:disabled)")?.focus({ preventScroll: true }); }
            else if (event.key === "Enter" && input.value.trim()) { event.preventDefault(); choose(input.value); }
        });
        render();
        this.bindDialogKeys(this.modalEl);
        // Only keyboard-originated opens explicitly focus search.
        if (this.options.returnFocusEl) this.focusDialogInput(input);
    }
}

// BEGIN SHARED SETTINGS — generated from shared/settings.js
// Native Setting keeps its components and callbacks. Plugin rows own their DOM
// classes so host settings snippets cannot become a second layout owner.
function createPluginSettingClass(NativeSetting) {
    return class PluginSettingRow extends NativeSetting {
        constructor(parent) {
            super(parent);
            for (const [key, nativeClass, ownClass] of [
                ["settingEl", "setting-item", "ui-setting-row"],
                ["infoEl", "setting-item-info", "ui-setting-info"],
                ["nameEl", "setting-item-name", "ui-setting-name"],
                ["descEl", "setting-item-description", "ui-setting-description"],
                ["controlEl", "setting-item-control", "ui-setting-control"]
            ]) {
                this[key].classList.replace(nativeClass, ownClass);
            }
        }
        addToggle(callback) {
            return super.addToggle(control => {
                control.toggleEl.classList.replace("checkbox-container", "ui-setting-toggle");
                callback(control);
            });
        }
        addText(callback) {
            return super.addText(control => {
                control.inputEl.classList.add("ui-setting-input");
                callback(control);
            });
        }
        addTextArea(callback) {
            return super.addTextArea(control => {
                control.inputEl.classList.add("ui-setting-input");
                callback(control);
            });
        }
        addDropdown(callback) {
            return super.addDropdown(control => {
                control.selectEl.classList.add("ui-setting-input");
                callback(control);
            });
        }
        addButton(callback) {
            return super.addButton(control => {
                control.buttonEl.classList.add("ui-setting-action");
                callback(control);
                if (control.buttonEl.classList.contains("mod-cta")) {
                    control.buttonEl.classList.replace("mod-cta", "ui-setting-primary");
                }
            });
        }
        addPicker(callback) {
            this.settingEl.classList.add("ui-setting-block");
            return super.addButton(control => {
                control.buttonEl.classList.add("ui-setting-picker");
                callback(control);
            });
        }
        addExtraButton(callback) {
            return super.addExtraButton(control => {
                control.extraSettingsEl.classList.add("ui-setting-icon");
                callback(control);
            });
        }
    };
}
// END SHARED SETTINGS

const DidaSettingRow = createPluginSettingClass(obsidian_1.Setting);

class DidaBridgeSettingTab extends obsidian_1.PluginSettingTab {
    constructor(app, plugin) {
        super(app, plugin);
        this.plugin = plugin;
        this._activeSettingsTab = "general";
        this._settingsVisible = false;
        plugin.register?.(()=>this._stopFeishuLoginPoll?.());
    }
    hide() {
        this._stopFeishuLoginPoll?.();
        this._hoverHintObserver?.disconnect();
        this._hoverHintObserver = null;
        this._settingsVisible = false;
        closeDidaOwnedDialogs(this.containerEl, { force: true });
        this.containerEl.empty();
    }
    openDialog(Dialog, options) {
        const root = this.containerEl;
        const moduleId = this._activeSettingsTab;
        const isOwnerActive = () => this._settingsVisible && root.isConnected && !this.plugin.unloading && this._activeSettingsTab === moduleId;
        if (!isOwnerActive()) return null;
        root._dbChildDialogs ||= new Set();
        if (!closeDidaOwnedDialogs(root)) return null;
        const doc = root.ownerDocument;
        const focused = root.contains(doc.activeElement) && doc.activeElement.matches?.(":focus-visible") ? doc.activeElement : null;
        const dialog = new Dialog(this.app, { ...options, swipeBack: this.plugin.swipeBack, isOwnerActive, returnFocusEl: focused });
        root._dbChildDialogs.add(dialog);
        dialog.dialogScope.add(() => root._dbChildDialogs.delete(dialog));
        dialog.open();
        return dialog;
    }
    createSettingsGroup(parent, title = "") {
        const group = parent.createDiv({ cls: "dida-bridge-settings-group" });
        if (title) group.createDiv({ cls: "dida-bridge-settings-group-title", text: title, attr: { role: "heading", "aria-level": "3" } });
        return group;
    }
    addPathSetting(parent, { name, desc, value, onClick }) {
        const setting = new DidaSettingRow(parent).setName(name).setDesc(desc);
        setting.settingEl.addClass("ui-setting-block");
        let field;
        setting.addButton(component => {
            const button = component.buttonEl;
            button.removeClass("ui-setting-action");
            button.addClass("dida-bridge-settings-path");
            initializeDidaInteractionElement(button, "action");
            button.setAttribute("aria-haspopup", "dialog");
            const icon = button.createSpan({ attr: { "aria-hidden": "true" } });
            (0, obsidian_1.setIcon)(icon, "folder");
            const label = button.createSpan({ cls: "dida-bridge-settings-path-label" });
            const arrow = button.createSpan({ attr: { "aria-hidden": "true" } });
            (0, obsidian_1.setIcon)(arrow, "chevron-right");
            const setValue = next => {
                label.textContent = next;
                button.setAttribute("aria-label", `${name}：${next}`);
            };
            setValue(value);
            component.onClick(onClick);
            field = { button, setValue };
        });
        return field;
    }
    addDirectorySetting(parent, { key, name, desc, normalize, onChange, onCommit }) {
        const field = this.addPathSetting(parent, { name, desc, value: this.plugin.settings[key],
            onClick: () => this.openDialog(DidaVaultFolderModal, {
                title: name, initialValue: this.plugin.settings[key],
                onSubmit: async path => {
                    const next = normalize(path), previous = this.plugin.settings[key];
                    if (onCommit) {
                        await onCommit(next, previous);
                        field.setValue(this.plugin.settings[key]);
                        onChange?.();
                        return;
                    }
                    if (next === previous) return;
                    const update = value => {
                        this.plugin.settings[key] = value;
                        field.setValue(value);
                    };
                    update(next);
                    try { await this.plugin.saveSettings(); }
                    catch (error) { if (this.plugin.settings[key] === next) update(previous); throw error; }
                    onChange?.();
                }
            })
        });
    }
    display() {
        this._stopFeishuLoginPoll?.();
        if (!closeDidaOwnedDialogs(this.containerEl)) return;
        this._hoverHintObserver ??= installPluginHoverHintSuppression();
        this._hoverHintObserver.observeRoot(this.containerEl);
        this._settingsVisible = true;
        const { containerEl } = this;
        containerEl.empty();
        containerEl.addClass("dida-bridge-settings-page");

        const renderGeneral = card => {
            this._stopFeishuLoginPoll?.();
            const connection = this.createSettingsGroup(card, "我的飞书");
            const stateRow = new DidaSettingRow(connection).setName("账号").setDesc(this.plugin.feishuConnectionDescription());
            const feedback = connection.createDiv({cls:"dida-feishu-feedback", attr:{role:"status","aria-live":"polite"}});
            let lastError = "", appIdCandidate = this.plugin.settings.feishuAppId || "", secretCandidate = "", secretInput;
            let stopped=false, refreshAfterAction=()=>{};
            const active=()=>!stopped && card.isConnected && this._settingsVisible && !this.plugin.unloading;
            const message=(text,error="")=>{if(!active())return;feedback.setText(text);lastError=error;feedback.classList.toggle("is-error",Boolean(error));};
            const action=async(button,fn)=>{
                if(this._feishuSettingsBusy)return false;
                this._feishuSettingsBusy=true;button?.setDisabled(true);
                try { await fn();return true; }
                catch(error){const text=errorMessage(error,"飞书操作未完成");message(text.split("。",1)[0],text);return false;}
                finally{this._feishuSettingsBusy=false;secretCandidate="";secretInput?.setValue("");button?.setDisabled(false);if(active())refreshAfterAction();}
            };
            const flow=()=>FEISHU_DEVICE_FLOW_RUNTIME.get(this.plugin.settings);
            const linkBox=connection.createDiv({cls:"dida-feishu-login-link"});
            const renderLink=()=>{
                linkBox.empty();const value=flow();if(!value || value.granted || value.terminal)return;
                linkBox.createEl("a",{text:"打开飞书完成登录",attr:{href:value.verificationComplete,target:"_blank",rel:"noopener noreferrer"}});
                linkBox.createDiv({text:`验证码 ${value.userCode} · 完成后回到这里，会自动检查。`});
            };
            let loginButton, refreshButton;
            const directoryText=()=>fsDirectorySummary(this.plugin.settings.feishuDirectory, this.plugin.settings.feishuUserInfo?.openId);
            const readCurrent=async(probeFields=false)=>{
                if(!this.plugin.isConfigured())throw fsError("请先登录你的飞书");
                if(probeFields){
                    const project=this.plugin.settings.projects.find(p=>p.id && p.id!=="inbox");
                    if(project){try{await this.plugin.runRemoteOperation(()=>new FeishuTaskApi(this.plugin.settings,this.plugin.lifecycleAbortController.signal).probeFieldRead(project.id));this.plugin.feishuFieldProbeIssue="";}
                    catch(error){this.plugin.feishuFieldProbeIssue=`自定义字段只读核验：${errorMessage(error,"核验未完成")}`;}}
                }
                const result=await this.plugin.feishuPull(false);
                let directory;
                try{directory=await this.plugin.feishuRefreshDirectory();}
                catch(error){message("清单已读取，员工读取未完成。",errorMessage(error,"员工读取失败"));return;}
                if(result?.projectErrors?.length || result?.taskErrors?.length){message("部分任务读取未完成，已有缓存保留。",[...(result.projectErrors||[]),...(result.taskErrors||[])].map(e=>e.message).join("\n"));return;}
                if(!directory.complete){message(fsDirectorySummary(directory,this.plugin.settings.feishuUserInfo?.openId),directory.warnings.join("\n"));return;}
                message(`已读取 ${this.plugin.settings.projects.length} 个清单、${result?.remoteCount||0} 个任务、${directory.users.filter(u=>u.active!==false).length} 位人员。`,this.plugin.feishuFieldProbeIssue||"");
            };
            let timer=null;
            const schedule=(delay=0)=>{
                const current=flow();if(!current||current.paused||current.terminal)return;
                const wait=Math.max(5000,(current.interval||5)*1000,delay,(current.nextPollAt||0)-Date.now());
                current.nextPollAt=Date.now()+wait;
                if(!active())return;
                window.clearTimeout(timer);timer=window.setTimeout(()=>void poll(),wait);
            };
            const continueLogin=async()=>{
                window.clearTimeout(timer);timer=null;
                const attemptFlow=flow();if(attemptFlow)attemptFlow.nextPollAt=0;
                let result;
                try{result=await this.plugin.feishuOAuthFinish();}
                catch(error){
                    renderLink();
                    const current=flow();
                    if(current===attemptFlow && current?.retryable && (current.retryCount||0)<2 && current.retryScheduledSerial!==current.failureSerial){
                        current.retryScheduledSerial=current.failureSerial;current.retryCount=(current.retryCount||0)+1;current.paused=false;
                        schedule(Math.max(current.retryAfterMs||0,5000*Math.pow(2,current.retryCount)));
                    }
                    throw error;
                }
                const current=flow();
                if(result?.pending){if(current){current.paused=false;current.retryCount=0;}message("等待飞书确认；当前登录尚未保存。","");schedule();return;}
                renderLink();message(`已完成登录 ${result?.name||""}，正在读取清单和人员…`);
                this.plugin.feishuFieldProbeIssue="";
                await readCurrent();
            };
            const poll=async()=>{
                const current=flow();if(!active()||!current||current.paused||current.terminal)return;
                if(document.hidden || this._feishuSettingsBusy || (current.nextPollAt||0)>Date.now()){schedule();return;}
                await action(null,continueLogin);
            };
            this._stopFeishuLoginPoll=()=>{stopped=true;window.clearTimeout(timer);timer=null;};
            const startLogin=async()=>{
                if(!FEISHU_AUTH_RUNTIME.get(this.plugin.settings)?.configured() || secretCandidate || appIdCandidate!==this.plugin.settings.feishuAppId)
                    await this.plugin.feishuConnect({appId:appIdCandidate,secret:secretCandidate});
                const current=flow();
                if(current && !current.terminal){current.retryCount=0;await continueLogin();return;}
                await this.plugin.feishuOAuthStart();
                renderLink();message("打开上方飞书链接登录；返回后自动继续。 ");schedule();
            };
            new DidaSettingRow(connection).setName("连接")
                .addButton(b=>{loginButton=b;b.setButtonText("登录飞书").setCta().onClick(()=>void action(b,startLogin));})
                .addButton(b=>{refreshButton=b;b.setButtonText("刷新").onClick(()=>void action(b,async()=>{const current=flow();if(current){current.retryCount=0;await continueLogin();}else await readCurrent(true);}));});
            const directoryRow=new DidaSettingRow(connection).setName("组织架构").setDesc(directoryText());
            const fieldRow=new DidaSettingRow(connection).setName("标签与优先级")
                .addButton(b=>b.setButtonText("补充授权").onClick(()=>void action(b,startLogin)));
            new DidaSettingRow(connection).setName("任务管理").setDesc("清单和负责人在任务中心管理；员工直接在飞书处理。")
                .addButton(b=>b.setButtonText("打开").onClick(()=>void this.plugin.activateTaskCenter()));

            const legacyGroup=this.createSettingsGroup(card,"旧清单待处理");
            const legacyHost=legacyGroup.createDiv();let legacySignature="";
            const renderLegacy=()=>{
                const rows=this.plugin.settings.feishuLegacyProjects||[];
                legacyGroup.hidden=!rows.length;
                const key=JSON.stringify(rows.map(p=>[p.id,p.name]));if(key===legacySignature)return;legacySignature=key;
                legacyHost.empty();
                for(const project of rows)new DidaSettingRow(legacyHost).setName(project.name)
                    .setDesc("只给你本人可编辑权限；不新建副本，不共享给其他员工。")
                    .addButton(b=>b.setButtonText("加入我的飞书").onClick(()=>void action(b,async()=>{
                        const verified=await this.plugin.feishuRecoverPersonalList(project.id);
                        message(`已用你的账号回读确认「${verified.name}」可访问。`);
                        if(/^https:\/\/(?:[A-Za-z0-9-]+\.)?feishu\.cn\//.test(verified.feishuUrl||""))
                            feedback.createEl("a",{text:" 在飞书打开",attr:{href:verified.feishuUrl,target:"_blank",rel:"noopener noreferrer"}});
                    })));
            };
            renderLegacy();

            const advanced=card.createEl("details",{cls:"dida-feishu-details"});
            advanced.createEl("summary",{text:"应用配置"});
            const config=this.createSettingsGroup(advanced);
            new DidaSettingRow(config).setName("App ID").addText(t=>t.setPlaceholder("cli_…").setValue(appIdCandidate).onChange(v=>appIdCandidate=v.trim()));
            new DidaSettingRow(config).setName("App Secret").setDesc("仅保存在本机 Obsidian 密钥存储，不写进任务缓存。")
                .addText(t=>{secretInput=t;t.inputEl.type="password";t.inputEl.autocomplete="new-password";t.inputEl.spellcheck=false;t.setPlaceholder(this.plugin.feishuReadSecret()?"已保存；留空不改":"仅在本机填写").onChange(v=>secretCandidate=v.trim());});
            new DidaSettingRow(config).setName("保存配置").setDesc("保存后点击上方“登录飞书”。已有配置不用重复填写。")
                .addButton(b=>b.setButtonText("保存").onClick(()=>void action(b,async()=>{await this.plugin.feishuConnect({appId:appIdCandidate,secret:secretCandidate});message("应用配置已保存，下一步登录你的飞书。");})));
            new DidaSettingRow(config).setName("退出登录").setDesc("停止本人任务操作，保留清单、任务及草稿；不会切换成应用身份继续写。")
                .addButton(b=>b.setButtonText("退出").onClick(()=>void action(b,async()=>{window.clearTimeout(timer);timer=null;await this.plugin.feishuOAuthDisconnect();renderLink();message("已退出登录，本端数据保留。");})));
            if(!this.plugin.settings.feishuAppId)advanced.open=true;

            const diagnostics=card.createEl("details",{cls:"dida-feishu-details"});diagnostics.createEl("summary",{text:"诊断与旧清单检查"});
            const diagnosticsHost=diagnostics.createDiv({cls:"dida-feishu-diagnostics"});
            new DidaSettingRow(diagnostics).setName("查找旧版本清单").setDesc("只读取此应用拥有的清单；不会修改权限或把它们混进个人目录。")
                .addButton(b=>b.setButtonText("检查").onClick(()=>void action(b,async()=>{const rows=await this.plugin.feishuDiscoverLegacyLists();message(rows.length?`发现 ${rows.length} 个待处理旧清单。`:"没有发现尚未加入你账号的应用清单。");})));
            const transactionsHost=diagnostics.createDiv();let txSignature="";
            const renderTransactions=()=>{
                const txs=this.plugin.settings.feishuListTransactions||{},key=JSON.stringify(txs);if(txSignature===key)return;txSignature=key;transactionsHost.empty();
                for(const [token,tx]of Object.entries(txs)){
                    let remoteId=tx.remoteId||"";
                    new DidaSettingRow(transactionsHost).setName(`待核对：${tx.name}`).setDesc("上次创建结果未确认，不会再次创建。仅在飞书核对后关联实际清单。")
                        .addText(t=>t.setPlaceholder("实际清单 GUID").setValue(remoteId).onChange(v=>remoteId=v.trim()))
                        .addButton(b=>b.setButtonText("关联").onClick(()=>void action(b,()=>this.plugin.feishuResolveListCreate(token,remoteId))));
                }
            };
            const conflicts=this.createSettingsGroup(card,"需要处理的冲突");
            const conflictHost=conflicts.createDiv();let conflictSignature="";
            const renderConflicts=()=>{
                const conflictsData=this.plugin.settings.feishuConflicts||{},ids=Object.keys(conflictsData),key=JSON.stringify(conflictsData);
                conflicts.hidden=!ids.length;if(conflictSignature===key)return;conflictSignature=key;conflictHost.empty();
                for(const id of ids)new DidaSettingRow(conflictHost).setName(this.plugin.settings.localTasks[id]?.title||id)
                    .setDesc(`双方都修改了：${conflictsData[id].join("、")}。选择后再从同步页提交。`)
                    .addButton(b=>b.setButtonText("保留本端").onClick(()=>void action(b,()=>this.plugin.feishuResolveConflict(id,"local"))))
                    .addButton(b=>b.setButtonText("采用飞书").onClick(()=>void action(b,()=>this.plugin.feishuResolveConflict(id,"remote"))));
            };
            const preferences=card.createEl("details",{cls:"dida-feishu-details"});preferences.createEl("summary",{text:"笔记与交互"});
            this.addDirectorySetting(this.createSettingsGroup(preferences),{key:"noteFolder",name:"飞书任务笔记目录",desc:"不扫描或接管旧滴答笔记。",
                normalize:value=>normalizeVaultRelativeFolder(value,"飞书任务笔记"),onCommit:next=>this.plugin.migrateBoundNotesToFolder(next)});
            new DidaSettingRow(preferences).setName("删除前确认").addToggle(t=>t.setValue(this.plugin.settings.confirmBeforeDelete!==false).onChange(async value=>{this.plugin.settings.confirmBeforeDelete=value;await this.plugin.saveSettings();}));
            new DidaSettingRow(preferences).setName("右滑返回").addToggle(t=>t.setValue(this.plugin.settings.swipeBackEnabled!==false).onChange(async value=>{this.plugin.settings.swipeBackEnabled=value;await this.plugin.saveSettings();}));
            refreshAfterAction=()=>{
                const current=flow();
                stateRow.setDesc(current?`${this.plugin.feishuConnectionDescription()}；新登录：${current.stage||"等待飞书确认"}${current.lastError?"（未完成，请看诊断）":"（尚未保存）"}`:this.plugin.feishuConnectionDescription());directoryRow.setDesc(directoryText());
                const readRequired=fsFieldAuthorizationRequired(this.plugin.settings,false),writeRequired=fsFieldAuthorizationRequired(this.plugin.settings,true);
                fieldRow.settingEl.hidden=!this.plugin.isConfigured() || !writeRequired;
                fieldRow.setDesc(readRequired?"当前已保存登录尚未确认自定义字段读取权限。刷新可只读核验；若有待完成登录，刷新先继续该登录。写权限须由飞书授予。":"当前登录可读取标签与优先级，尚未确认写权限；补充授权用于写入，不影响读取。" );
                loginButton?.setButtonText(current?.terminal?"重新开始登录":current?"继续登录":this.plugin.isConfigured()?"重新登录":"登录飞书");
                refreshButton?.setDisabled(!current && !this.plugin.isConfigured());
                const fieldIssues=[...new Set(Object.values(this.plugin.settings.localTasks||{}).map(t=>t.feishu?.fieldReadIssue).filter(Boolean))];
                const noteIssues=[...(this.plugin.boundNoteIssues?.values?.()||[])].map(x=>x.message);
                diagnosticsHost.setText([...new Set([current?.lastError,lastError,this.plugin.feishuFieldProbeIssue,...(this.plugin.settings.feishuDirectory?.warnings||[]),...fieldIssues,...noteIssues].filter(Boolean))].join("\n") || "暂无错误记录。通讯录按本人授权范围读取。");
                renderLegacy();renderTransactions();renderConflicts();
            };
            refreshAfterAction();renderLink();if(flow()?.lastError)message("当前登录尚未完成，请查看诊断或点击继续登录。",flow().lastError);if(flow())schedule();
        };

        const renderSync = card => {
            const recovery = this.createSettingsGroup(card,"同步与恢复");
            new DidaSettingRow(recovery).setName("同步规则")
                .setDesc("编辑后仅提交相关任务；读取不推送草稿；同字段冲突需要明确选择。失败、限流、未知写入不自动重试。任务只使用本人身份访问有权限的清单。");
            new DidaSettingRow(recovery).setName("导出本端恢复副本")
                .setDesc("发生存储异常或 NAS 改动时，先导出当前内存草稿再关闭插件。文件含任务内容，不含 App Secret 或 Token；保存在本插件目录，不覆盖原缓存。")
                .addButton(button => button.setButtonText("导出").onClick(async () => {
                    button.setDisabled(true);
                    try { const path = await this.plugin.feishuExportRecovery(); new obsidian_1.Notice(`已保存恢复副本：${path}`,10000); }
                    catch(error) { new obsidian_1.Notice(errorMessage(error,"导出恢复副本失败"),6000); }
                    finally { button.setDisabled(false); }
                }));
            new DidaSettingRow(recovery).setName("提交待处理修改")
                .setDesc("先读取并检测冲突，再提交本端草稿；不是日常刷新。")
                .addButton(button=>button.setButtonText("同步").onClick(async()=>{
                    if(this._feishuSettingsBusy)return;this._feishuSettingsBusy=true;button.setDisabled(true);
                    try{await this.plugin.manualSyncNow(true);}catch(error){new obsidian_1.Notice(errorMessage(error,"同步未完成"),6000);}
                    finally{this._feishuSettingsBusy=false;button.setDisabled(false);}
                }));
            new DidaSettingRow(recovery).setName("定时读取飞书")
                .setDesc("可选每两分钟读取；当前状态以开关为准。不自动重试失败写入。")
                .addToggle(t=>t.setValue(this.plugin.settings.feishuAutoRefresh===true).onChange(async value=>{
                    this.plugin.settings.feishuAutoRefresh=value;await this.plugin.saveSettings();
                    if(value)this.plugin.startCurrentStateSync();else this.plugin.pauseCurrentStateSync();
                }));
        };

        const modules = [
            { id: "general", label: "常规", title: "常规", desc: "账号连接、常用操作与任务笔记。", render: renderGeneral },
            { id: "sync", label: "同步", title: "同步", desc: "同步规则与原文恢复副本。", render: renderSync },
        ];
        const moduleById = new Map(modules.map(module => [module.id, module]));
        const tabs = containerEl.createDiv({ cls: "dida-bridge-settings-tabs", attr: { role: "tablist", "aria-label": "Dida Bridge 设置分类" } });
        const panelId = "dida-bridge-settings-module-panel";
        const panel = containerEl.createDiv({ cls: "dida-bridge-settings-module", attr: { id: panelId, role: "tabpanel" } });
        const tabButtons = new Map();
        const renderModule = (id, focus = false) => {
            const module = moduleById.get(id) || modules[0];
            const focusTab = () => {
                const button = tabButtons.get(module.id);
                if (!button) return;
                button.focus({ preventScroll: true });
                const outer = tabs.getBoundingClientRect(), inner = button.getBoundingClientRect();
                if (inner.left < outer.left) tabs.scrollLeft += inner.left - outer.left;
                else if (inner.right > outer.right) tabs.scrollLeft += inner.right - outer.right;
            };
            if (panel.dataset.dbModuleId === module.id && panel.childElementCount) {
                if (focus) focusTab();
                return;
            }
            if (!closeDidaOwnedDialogs(containerEl)) return;
            this._activeSettingsTab = module.id;
            for (const [key, button] of tabButtons) {
                const selected = key === module.id;
                button.toggleClass("is-selected", selected);
                button.setAttribute("aria-selected", String(selected));
                button.tabIndex = selected ? 0 : -1;
            }
            this._stopFeishuLoginPoll?.();
            panel.empty();
            panel.dataset.dbModuleId = module.id;
            panel.setAttribute("aria-labelledby", `dida-bridge-settings-tab-${module.id}`);
            const heading = panel.createDiv({ cls: "dida-bridge-settings-module-head" });
            heading.createDiv({ cls: "dida-bridge-settings-section-title", text: module.title });
            heading.createDiv({ cls: "dida-bridge-settings-section-desc", text: module.desc });
            const card = panel.createDiv({ cls: "dida-bridge-settings-card" });
            module.render(card);
            if (focus) focusTab();
        };
        const moveTab = (fromId, key) => {
            const index = Math.max(0, modules.findIndex(module => module.id === fromId));
            let next = index;
            if (key === "ArrowLeft") next = (index - 1 + modules.length) % modules.length;
            else if (key === "ArrowRight") next = (index + 1) % modules.length;
            else if (key === "Home") next = 0;
            else if (key === "End") next = modules.length - 1;
            else return false;
            renderModule(modules[next].id, true);
            return true;
        };
        for (const module of modules) {
            const button = createDidaButton(tabs, "choice", {
                cls: "dida-bridge-settings-tab",
                text: module.label,
                attr: {
                    id: `dida-bridge-settings-tab-${module.id}`,
                    type: "button", role: "tab", "aria-selected": "false", "aria-controls": panelId, tabindex: "-1"
                }
            });
            button.addEventListener("click", () => renderModule(module.id));
            button.addEventListener("keydown", event => {
                if (event.isComposing || event.altKey || event.ctrlKey || event.metaKey) return;
                if (!moveTab(module.id, event.key))
                    return;
                event.preventDefault();
            });
            tabButtons.set(module.id, button);
        }
        renderModule(moduleById.has(this._activeSettingsTab) ? this._activeSettingsTab : modules[0].id);
    }


}

